-- pos-accounting: Flyway baseline (flattened 2026-09-09 from the previous migration history) with the
-- ADR-0062 tenancy schema folded in. Generated by scripts/db/tenancy/flatten.py from a pg_dump of a
-- database migrated with the retired scripts; the tenancy additions are mechanical and are listed in
-- docs/TENANCY_SCHEMA.md. Global (unscoped) tables: src/main/resources/db/tenancy-global-tables.txt.
--
-- Tenant context: app_current_tenant() reads the session setting app.current_tenant, which the
-- TenantAwareDataSource (pos-tenancy-common, plan WS1) binds per checkout. Until then the owner role
-- carries a transitional default (postgres/init-tenancy.sh) and tests set it per connection.
-- With nothing bound: NULL -> every scoped table reads as empty and refuses inserts (fail closed).

-- Functions are emitted before the tables they reference (pg_dump order); do not validate bodies.
SET check_function_bodies = false;

CREATE OR REPLACE FUNCTION public.app_current_tenant() RETURNS uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$ SELECT NULLIF(current_setting('app.current_tenant', true), '')::uuid $$;

CREATE FUNCTION public.assert_journal_entry_balanced(p_journal_entry_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_status    journal_entry.status%TYPE;
    v_imbalance numeric(19, 4);
BEGIN
    SELECT status INTO v_status FROM journal_entry WHERE journal_entry_id = p_journal_entry_id FOR NO KEY UPDATE;

    -- Parent deleted in the same transaction, or entry not POSTED: exempt.
    IF v_status IS NULL OR v_status <> 'POSTED' THEN
        RETURN;
    END IF;

    SELECT COALESCE(SUM(debit_amount) - SUM(credit_amount), 0)
      INTO v_imbalance
      FROM journal_entry_line
     WHERE journal_entry_id = p_journal_entry_id;

    IF ABS(v_imbalance) > 0.0001 THEN
        RAISE EXCEPTION
            'journal entry % is POSTED but unbalanced: sum(debit) - sum(credit) = %',
            p_journal_entry_id, v_imbalance
            USING ERRCODE = '23514'; -- check_violation
    END IF;
END;
$$;

CREATE FUNCTION public.trg_journal_entry_line_balance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        PERFORM assert_journal_entry_balanced(OLD.journal_entry_id);
    ELSE
        PERFORM assert_journal_entry_balanced(NEW.journal_entry_id);
        IF TG_OP = 'UPDATE' AND NEW.journal_entry_id IS DISTINCT FROM OLD.journal_entry_id THEN
            -- Line moved between entries: re-check the entry it left as well.
            PERFORM assert_journal_entry_balanced(OLD.journal_entry_id);
        END IF;
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION public.trg_journal_entry_post_balance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'POSTED' THEN
        PERFORM assert_journal_entry_balanced(NEW.journal_entry_id);
    END IF;
    RETURN NULL;
END;
$$;

CREATE TABLE public.accounting_audit_log (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    "timestamp" timestamp(6) with time zone NOT NULL,
    audit_log_id uuid NOT NULL,
    entity_id uuid NOT NULL,
    entity_type character varying(50) NOT NULL,
    ip_address character varying(50),
    operation character varying(50) NOT NULL,
    user_id character varying(50) NOT NULL,
    trace_id character varying(100),
    justification character varying(2000),
    new_value text,
    old_value text
);

CREATE TABLE public.accounting_configuration (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    config_id uuid NOT NULL,
    config_key character varying(100) NOT NULL,
    config_value character varying(500) NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    created_by character varying(50) NOT NULL,
    modified_at timestamp(6) with time zone NOT NULL,
    modified_by character varying(50) NOT NULL
);

CREATE TABLE public.accounting_event (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    attempt_count integer,
    processed_at timestamp(6) with time zone,
    received_at timestamp(6) with time zone NOT NULL,
    sequence_number bigint,
    transaction_date timestamp(6) without time zone NOT NULL,
    version bigint NOT NULL,
    event_id uuid NOT NULL,
    journal_entry_id uuid,
    organization_id uuid,
    status character varying(20) NOT NULL,
    mapping_version_attempted character varying(50),
    event_type character varying(100) NOT NULL,
    failure_reason_code character varying(100),
    final_posting_reference_id character varying(100),
    resolved_by_user_id character varying(100),
    source_system character varying(100) NOT NULL,
    error_message character varying(2000),
    failure_details character varying(4000),
    payload jsonb NOT NULL,
    idempotency_outcome character varying(20),
    ingestion_id uuid,
    domain_key_id character varying(255),
    invoice_id uuid,
    event_reference character varying(20),
    CONSTRAINT accounting_event_status_check CHECK (((status)::text = ANY (ARRAY[('RECEIVED'::character varying)::text, ('PROCESSING'::character varying)::text, ('PROCESSED'::character varying)::text, ('FAILED'::character varying)::text, ('SUSPENDED'::character varying)::text])))
);

CREATE TABLE public.accounting_location_fx_rate (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    fx_rate_id uuid NOT NULL,
    location_code character varying(100) NOT NULL,
    fiscal_year integer NOT NULL,
    local_currency_per_usd numeric(12,6) NOT NULL,
    average_rate numeric(12,6) NOT NULL,
    version integer,
    created_at timestamp(6) with time zone NOT NULL,
    modified_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT accounting_location_fx_rate_average_check CHECK ((average_rate > (0)::numeric)),
    CONSTRAINT accounting_location_fx_rate_per_usd_check CHECK ((local_currency_per_usd > (0)::numeric))
);

CREATE TABLE public.accounting_location_profile (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    profile_id uuid NOT NULL,
    location_code character varying(100) NOT NULL,
    location_label character varying(255) NOT NULL,
    currency_code character varying(3) NOT NULL,
    version integer,
    created_at timestamp(6) with time zone NOT NULL,
    modified_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.accounting_period (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    period_id uuid NOT NULL,
    period_code character varying(7) NOT NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    status character varying(10) NOT NULL,
    closed_at timestamp(6) with time zone,
    closed_by character varying(50),
    reopened_at timestamp(6) with time zone,
    reopened_by character varying(50),
    reopen_justification character varying(1000),
    created_at timestamp(6) with time zone NOT NULL,
    created_by character varying(50) NOT NULL,
    modified_at timestamp(6) with time zone NOT NULL,
    modified_by character varying(50) NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT accounting_period_date_check CHECK ((start_date <= end_date)),
    CONSTRAINT accounting_period_status_check CHECK (((status)::text = ANY (ARRAY[('OPEN'::character varying)::text, ('CLOSED'::character varying)::text])))
);

CREATE TABLE public.accounting_sequence (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    sequence_id uuid NOT NULL,
    scope_key character varying(20) NOT NULL,
    next_value bigint NOT NULL,
    CONSTRAINT accounting_sequence_next_value_check CHECK ((next_value >= 1))
);

CREATE TABLE public.accounting_status_sync_audit (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    latency_ms bigint,
    synced_at timestamp(6) with time zone NOT NULL,
    id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    new_status character varying(50) NOT NULL,
    old_status character varying(50),
    sync_source character varying(100) NOT NULL,
    event_id character varying(255) NOT NULL,
    CONSTRAINT accounting_status_sync_audit_new_status_check CHECK (((new_status)::text = ANY (ARRAY[('PENDING_POSTING'::character varying)::text, ('POSTED'::character varying)::text, ('RECONCILED'::character varying)::text, ('REJECTED'::character varying)::text, ('REVERSED'::character varying)::text, ('VOIDED'::character varying)::text, ('ON_HOLD'::character varying)::text, ('DISPUTED'::character varying)::text]))),
    CONSTRAINT accounting_status_sync_audit_old_status_check CHECK (((old_status)::text = ANY (ARRAY[('PENDING_POSTING'::character varying)::text, ('POSTED'::character varying)::text, ('RECONCILED'::character varying)::text, ('REJECTED'::character varying)::text, ('REVERSED'::character varying)::text, ('VOIDED'::character varying)::text, ('ON_HOLD'::character varying)::text, ('DISPUTED'::character varying)::text])))
);

CREATE TABLE public.ap_payment (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    currency character varying(3) NOT NULL,
    fee_amount numeric(19,4),
    gross_amount numeric(19,4) NOT NULL,
    net_amount numeric(19,4),
    unapplied_amount numeric(19,4),
    created_at timestamp(6) with time zone NOT NULL,
    gateway_timestamp timestamp(6) with time zone,
    gl_posted_at timestamp(6) with time zone,
    payment_date timestamp(6) without time zone,
    bank_account_id uuid,
    gl_journal_entry_id uuid,
    payment_id uuid NOT NULL,
    vendor_bill_id uuid,
    vendor_id uuid NOT NULL,
    payment_method character varying(20),
    status character varying(30) NOT NULL,
    created_by character varying(50) NOT NULL,
    payment_ref character varying(100) NOT NULL,
    gateway_transaction_id character varying(200),
    vendor_name character varying(200),
    memo character varying(1000),
    gateway_response character varying(2000),
    gl_post_error character varying(2000),
    CONSTRAINT ap_payment_payment_method_check CHECK (((payment_method)::text = ANY (ARRAY[('ACH'::character varying)::text, ('CHECK'::character varying)::text, ('WIRE'::character varying)::text, ('CREDIT_CARD'::character varying)::text, ('OTHER'::character varying)::text]))),
    CONSTRAINT ap_payment_status_check CHECK (((status)::text = ANY (ARRAY[('INITIATED'::character varying)::text, ('GATEWAY_PENDING'::character varying)::text, ('GATEWAY_FAILED'::character varying)::text, ('GATEWAY_SUCCEEDED'::character varying)::text, ('GL_POST_PENDING'::character varying)::text, ('GL_POSTED'::character varying)::text, ('GL_POST_FAILED'::character varying)::text])))
);

CREATE TABLE public.ap_payment_allocation (
