CREATE TABLE public.audit_trail_entry (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    adjusted_price numeric(19,4),
    original_price numeric(19,4),
    refund_amount numeric(19,4),
    "timestamp" timestamp(6) with time zone NOT NULL,
    audit_id uuid NOT NULL,
    invoice_id uuid,
    line_item_id uuid,
    order_id uuid,
    payment_id uuid,
    source_event_id uuid,
    accounting_intent character varying(50),
    accounting_status character varying(50) NOT NULL,
    cancellation_type character varying(50),
    exception_type character varying(50) NOT NULL,
    gl_reversal_status character varying(50),
    original_payment_status character varying(50),
    override_amount_or_percent character varying(50),
    policy_validation_result character varying(50),
    policy_version character varying(50) NOT NULL,
    refund_method character varying(50),
    refund_type character varying(50),
    actor_role character varying(100) NOT NULL,
    authorization_level character varying(100) NOT NULL,
    forbidden_category_code character varying(100),
    expected_accounting_outcome character varying(1000),
    reason character varying(2000),
    actor_id character varying(255) NOT NULL,
    after_snapshot text,
    before_snapshot text,
    linked_source_ids text,
    partial_payment_info text,
    source_document_id character varying(255),
    CONSTRAINT audit_trail_entry_accounting_intent_check CHECK (((accounting_intent)::text = ANY (ARRAY[('REVENUE_ADJUSTMENT'::character varying)::text, ('PAYMENT_REVERSAL'::character varying)::text, ('CUSTOMER_CREDIT'::character varying)::text, ('WRITE_OFF'::character varying)::text, ('REVENUE_REVERSAL'::character varying)::text, ('PAYMENT_RECOVERY'::character varying)::text]))),
    CONSTRAINT audit_trail_entry_accounting_status_check CHECK (((accounting_status)::text = ANY (ARRAY[('PENDING_POSTING'::character varying)::text, ('POSTED'::character varying)::text, ('RECONCILED'::character varying)::text, ('REJECTED'::character varying)::text, ('REVERSED'::character varying)::text, ('VOIDED'::character varying)::text, ('ON_HOLD'::character varying)::text, ('DISPUTED'::character varying)::text]))),
    CONSTRAINT audit_trail_entry_cancellation_type_check CHECK (((cancellation_type)::text = ANY (ARRAY[('ORDER_CANCELLED'::character varying)::text, ('INVOICE_CANCELLED'::character varying)::text, ('PAYMENT_FAILED'::character varying)::text]))),
    CONSTRAINT audit_trail_entry_exception_type_check CHECK (((exception_type)::text = ANY (ARRAY[('PRICE_OVERRIDE'::character varying)::text, ('REFUND'::character varying)::text, ('CANCELLATION'::character varying)::text]))),
    CONSTRAINT audit_trail_entry_original_payment_status_check CHECK (((original_payment_status)::text = ANY (ARRAY[('PENDING'::character varying)::text, ('SETTLED'::character varying)::text, ('FAILED'::character varying)::text, ('AUTHORIZED'::character varying)::text]))),
    CONSTRAINT audit_trail_entry_policy_validation_result_check CHECK (((policy_validation_result)::text = ANY (ARRAY[('APPROVED'::character varying)::text, ('REJECTED_FORBIDDEN'::character varying)::text, ('REJECTED_THRESHOLD_EXCEEDED'::character varying)::text]))),
    CONSTRAINT audit_trail_entry_refund_method_check CHECK (((refund_method)::text = ANY (ARRAY[('VOID'::character varying)::text, ('CHARGEBACK'::character varying)::text, ('CASH_REFUND'::character varying)::text, ('CREDIT_MEMO'::character varying)::text]))),
    CONSTRAINT audit_trail_entry_refund_type_check CHECK (((refund_type)::text = ANY (ARRAY[('REVERSAL'::character varying)::text, ('CREDIT_MEMO'::character varying)::text, ('ADJUSTMENT'::character varying)::text])))
);

