    created_at timestamp(6) with time zone NOT NULL,
    credit_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    source_payment_id uuid NOT NULL,
    created_by character varying(50),
    trace_id character varying(100),
    status character varying(20) DEFAULT 'AVAILABLE'::character varying NOT NULL,
    applied_amount numeric(19,4) DEFAULT 0 NOT NULL,
    refunded_amount numeric(19,4) DEFAULT 0 NOT NULL,
    updated_at timestamp(6) with time zone,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT chk_customer_credit_consumed_within_amount CHECK (((applied_amount >= (0)::numeric) AND (refunded_amount >= (0)::numeric) AND ((applied_amount + refunded_amount) <= amount)))
);

