    gl_posted_at timestamp(6) with time zone,
    trace_id character varying(100),
    created_at timestamp(6) with time zone NOT NULL,
    created_by character varying(50),
    CONSTRAINT chk_customer_credit_transaction_amount_positive CHECK ((amount > (0)::numeric)),
    CONSTRAINT chk_customer_credit_transaction_invoice CHECK (((((transaction_type)::text = 'APPLICATION'::text) AND (invoice_id IS NOT NULL)) OR (((transaction_type)::text = 'REFUND'::text) AND (invoice_id IS NULL)))),
    CONSTRAINT chk_customer_credit_transaction_type CHECK (((transaction_type)::text = ANY ((ARRAY['APPLICATION'::character varying, 'REFUND'::character varying])::text[])))
);

