    CONSTRAINT gl_account_account_subtype_check CHECK (((account_subtype)::text = ANY (ARRAY[('RECEIVABLE'::character varying)::text, ('PAYABLE'::character varying)::text, ('BANK_CASH'::character varying)::text, ('UNDEPOSITED_FUNDS'::character varying)::text, ('TAX_PAYABLE'::character varying)::text, ('CURRENT_ASSET'::character varying)::text, ('FIXED_ASSET'::character varying)::text, ('CURRENT_LIABILITY'::character varying)::text, ('SALES'::character varying)::text, ('COST_OF_SALES'::character varying)::text, ('OPERATING_EXPENSE'::character varying)::text, ('OTHER'::character varying)::text]))),
    CONSTRAINT gl_account_account_type_check CHECK (((account_type)::text = ANY (ARRAY[('ASSET'::character varying)::text, ('LIABILITY'::character varying)::text, ('EQUITY'::character varying)::text, ('REVENUE'::character varying)::text, ('EXPENSE'::character varying)::text])))
);

