    posting_reference character varying(255),
    CONSTRAINT invoice_status_views_accounting_status_check CHECK (((accounting_status)::text = ANY (ARRAY[('PENDING_POSTING'::character varying)::text, ('POSTED'::character varying)::text, ('RECONCILED'::character varying)::text, ('REJECTED'::character varying)::text, ('REVERSED'::character varying)::text, ('VOIDED'::character varying)::text, ('ON_HOLD'::character varying)::text, ('DISPUTED'::character varying)::text]))),
    CONSTRAINT invoice_status_views_current_status_check CHECK (((current_status)::text = ANY (ARRAY[('PAID'::character varying)::text, ('PARTIALLY_PAID'::character varying)::text, ('UNPAID'::character varying)::text, ('FAILED'::character varying)::text, ('CHARGEBACK'::character varying)::text])))
);

