    reason_code character varying(50),
    source_event_type character varying(100),
    description character varying(500),
    justification character varying(1000),
    entry_number character varying(20),
    CONSTRAINT journal_entry_entry_type_check CHECK (((entry_type)::text = ANY (ARRAY[('EVENT_DRIVEN'::character varying)::text, ('MANUAL'::character varying)::text]))),
    CONSTRAINT journal_entry_reason_code_check CHECK (((reason_code)::text = ANY (ARRAY[('ACCRUAL_ADJUSTMENT'::character varying)::text, ('ERROR_CORRECTION'::character varying)::text, ('RECLASSIFICATION'::character varying)::text, ('DEPRECIATION'::character varying)::text, ('OTHER'::character varying)::text]))),
    CONSTRAINT journal_entry_status_check CHECK (((status)::text = ANY (ARRAY[('DRAFT'::character varying)::text, ('PENDING'::character varying)::text, ('POSTED'::character varying)::text, ('REVERSED'::character varying)::text])))
);

